import { ref } from 'vue'
import { pointsApi, type PointsStats } from '@/scripts/pointsApi'

export function usePointsStats() {
  const stats = ref<PointsStats>({
    balance: 0,
    totalEarned: 0,
    totalConsumed: 0
  })
  const loading = ref(false)
  const error = ref<string | null>(null)

  async function fetchStats() {
    loading.value = true
    error.value = null
    try {
      const data = await pointsApi.getStats()
      stats.value = data
    } catch (e) {
      error.value = e instanceof Error ? e.message : 'Failed to fetch stats'
    } finally {
      loading.value = false
    }
  }

  return { stats, loading, error, fetchStats }
}
